// Filter 7 Hari & Format Teks
// Mode: Run Once for All Items
const items = $input.all();

// Rentang waktu: 7 hari lalu (00:00:00) sampai akhir hari ini (23:59:59)
const today = new Date();
today.setHours(23, 59, 59, 999);
const sevenDaysAgo = new Date(today);
sevenDaysAgo.setDate(today.getDate() - 7);
sevenDaysAgo.setHours(0, 0, 0, 0);

const pad = (n) => String(n).padStart(2, '0');
const rupiah = (n) => 'Rp' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Sheet memakai format DD/MM/YYYY. Harus diparse manual agar JS tidak salah baca.
function parseTanggal(raw) {
  if (raw instanceof Date) return raw;
  if (typeof raw === 'number') {
    // serial date Google Sheets/Excel
    const d = new Date(Math.round((raw - 25569) * 86400 * 1000));
    return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  }
  const s = String(raw || '').trim().split(' ')[0];
  if (!s) return null;
  if (s.includes('/')) {
    const [day, month, year] = s.split('/').map(Number);
    if (!day || !month || !year || year < 1000) return null;
    return new Date(year, month - 1, day);
  }
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
  return null;
}

// Jumlah bisa berupa angka atau teks seperti "Rp25.000"
function parseJumlah(raw) {
  if (typeof raw === 'number') return raw;
  const s = String(raw || '').trim();
  if (/^\d+(\.\d+)?$/.test(s)) return parseFloat(s);
  const bersih = s.replace(/[^0-9,]/g, '').replace(',', '.');
  return parseFloat(bersih) || 0;
}

const terpilih = [];
let dilewati = 0;

for (const item of items) {
  const row = item.json;
  const rawDate = row['Tanggal'];
  const expenseDate = parseTanggal(rawDate);
  if (!expenseDate) { dilewati++; continue; }

  if (expenseDate >= sevenDaysAgo && expenseDate <= today) {
    terpilih.push({
      tanggal: expenseDate,
      rawDate: pad(expenseDate.getDate()) + '/' + pad(expenseDate.getMonth() + 1) + '/' + expenseDate.getFullYear(),
      kategori: row['Kategori'] || '-',
      deskripsi: row['Deskripsi'] || '-',
      metode: row['Metode Pembayaran'] || '-',
      penerima: row['Penerima'] || '-',
      jumlah: parseJumlah(row['Jumlah (IDR)'])
    });
  }
}

terpilih.sort((a, b) => a.tanggal - b.tanggal);

const rangeLabel = pad(sevenDaysAgo.getDate()) + '/' + pad(sevenDaysAgo.getMonth() + 1) + '/' + sevenDaysAgo.getFullYear() +
  ' - ' + pad(today.getDate()) + '/' + pad(today.getMonth() + 1) + '/' + today.getFullYear();

// Bangun string 'briefing' untuk AI
let formattedString = '📊 Data pengeluaran saya 7 hari terakhir (' + rangeLabel + '):\n\n';
let total = 0;
const perKategori = {};

for (const t of terpilih) {
  total += t.jumlah;
  perKategori[t.kategori] = (perKategori[t.kategori] || 0) + t.jumlah;
  formattedString +=
    ' - ' + t.rawDate + ' | ' + t.kategori + '\n' +
    '   ' + t.deskripsi + '\n' +
    '   Metode: ' + t.metode + '\n' +
    '   Penerima: ' + t.penerima + '\n' +
    '   💸 ' + rupiah(t.jumlah) + '\n\n';
}

// Total dihitung di JavaScript agar AI tidak salah hitung
if (terpilih.length > 0) {
  formattedString += 'RINGKASAN (sudah dihitung sistem):\n';
  formattedString += '- Jumlah transaksi: ' + terpilih.length + '\n';
  formattedString += '- Total pengeluaran: ' + rupiah(total) + '\n';
  formattedString += '- Total per kategori:\n';
  Object.entries(perKategori)
    .sort((a, b) => b[1] - a[1])
    .forEach(([k, v]) => { formattedString += '  * ' + k + ': ' + rupiah(v) + '\n'; });
}

return [{
  json: {
    hasExpenses: terpilih.length > 0,
    jumlahTransaksi: terpilih.length,
    totalPengeluaran: total,
    totalFormatted: rupiah(total),
    rentang: rangeLabel,
    baris_dilewati: dilewati,
    promptData: formattedString
  }
}];

